// Independent host builder. payload.S is explicit AArch64 source, not generated by Python.
use std::{collections::HashMap,env,fs,path::{Path,PathBuf},process::Command};
const BASE:usize=0x108daa0;
const LIMIT:usize=0x2560;
const SLOT:usize=0x22f6a00;
const RC:&[u8]=b"\non post-fs-data\n    exec u:r:init:s0 root root -- /system/bin/cnd --stage post-fs-data\n\non nonencrypted\n    exec_background u:r:init:s0 root root -- /system/bin/cnd --stage service\n\non property:vold.decrypt=trigger_restart_framework\n    exec_background u:r:init:s0 root root -- /system/bin/cnd --stage service\n";
fn run(prog:&str,args:&[&str])->String{let o=Command::new(prog).args(args).output().unwrap_or_else(|e|panic!("{prog}: {e}"));assert!(o.status.success(),"{prog}: {}",String::from_utf8_lossy(&o.stderr));String::from_utf8_lossy(&o.stdout).to_string()}
fn put32(b:&mut[u8],o:usize,v:u32){b.get_mut(o..o+4).expect("write bounds").copy_from_slice(&v.to_le_bytes());}
fn get32(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn branch(src:usize,dst:usize,link:bool)->u32{let d=dst as i64-src as i64;assert!(d%4==0&&(-0x8000000..0x8000000).contains(&d));(if link{0x94000000}else{0x14000000})|(((d>>2)as u32)&0x3ffffff)}
fn main(){
 let a:Vec<String>=env::args().collect();if a.len()!=4{eprintln!("Cairn V1.0.1\nUsage: {} STOCK_KERNEL STOCK_BOOT OUTPUT_DIR",a[0]);std::process::exit(2);}
 let stock=Path::new(&a[1]);let boot=Path::new(&a[2]);let out=PathBuf::from(&a[3]);fs::create_dir_all(&out).unwrap();
 let expected="ee05514a43870690e086872ae90b6db1d3e68ba3";
 assert_eq!(run("sha1sum",&[stock.to_str().unwrap()]).split_whitespace().next().unwrap(),expected,"wrong input kernel");
 let obj=out.join("payload.o");let elf=out.join("payload.elf");let bin=out.join("payload.bin");
 let asm=Path::new(env!("CARGO_MANIFEST_DIR")).join("payload.S");
 run("aarch64-linux-gnu-as",&["-o",obj.to_str().unwrap(),asm.to_str().unwrap()]);
 run("aarch64-linux-gnu-ld",&["-Ttext","0x108daa0","-o",elf.to_str().unwrap(),obj.to_str().unwrap()]);
 run("aarch64-linux-gnu-objcopy",&["-O","binary","--only-section=.text",elf.to_str().unwrap(),bin.to_str().unwrap()]);
 let nm=run("aarch64-linux-gnu-nm",&[elf.to_str().unwrap()]);let mut sy=HashMap::new();for l in nm.lines(){let p:Vec<_>=l.split_whitespace().collect();if p.len()==3{sy.insert(p[2].to_string(),usize::from_str_radix(p[0],16).unwrap()-BASE);}}
 let off=|n:&str|*sy.get(n).unwrap_or_else(||panic!("missing symbol {n}"));let mut pl=fs::read(&bin).unwrap();assert!(pl.len()<=LIMIT);
 let o=off("cairn_wl_slot_delta");let delta=SLOT as i64-(BASE+o)as i64;pl[o..o+8].copy_from_slice(&delta.to_le_bytes());
 let calls=[("cairn_wl_copy",0x101ebc0),("cairn_wl_alloc",0x35c688),("cairn_wl_free",0x35b930),("cairn_pd",0xe2968),("cairn_cm",0xe2f10),("cairn_ok_bl",0x104da58),("cairn_bad_bl",0x104da58),("cairn_stat_bl",0x104da58),("cairn_fac_bl",0x104da58),("cairn_cndstat_bl",0x104da58),("cairn_vr_blr",0x104da58),("cairn_vr_be",0x104da58),("cairn_vr_bc",0x101eec0),("cairn_fac_scf",0x7b1e0c),("cairn_exec_log",0x104da58)];
 for(n,t)in calls{let o=off(n);put32(&mut pl,o,branch(BASE+o,t,true));}
 for(n,t)in [("cairn_bprm_b",0x62f040),("cairn_sip_b",0x63bda8),("cairn_avc_b",0x63756c),("cairn_avcn_b",0x6373b8),("cairn_prctl_tail",0xcdbe0),("cairn_stat_ret",0x3daba0),("cairn_exec_j",0x3def5c),("cairn_exec_j2",0x3def5c),("cairn_fac_j",0x3d0ac4),("cairn_vr_j",0x3d1928)]{let o=off(n);put32(&mut pl,o,branch(BASE+o,t,false));}
 put32(&mut pl,off("cairn_add_len"),RC.len()as u32);let o=off("cairn_rc_add");assert!(o+RC.len()<=off("cairn_fmt_vrr"));pl[o..o+RC.len()].copy_from_slice(RC);
 fs::write(&bin,&pl).unwrap();let mut k=fs::read(stock).unwrap();assert_eq!(k.len(),SLOT);assert!(k[BASE..BASE+LIMIT].iter().all(|x|*x==0));k[BASE..BASE+pl.len()].copy_from_slice(&pl);
 for(addr,original,label)in [(0x62f03c,0xd503233f,"cairn_bprm"),(0x63bda4,0xd10143ff,"cairn_sip"),(0x637568,0xd101c3ff,"cairn_avc"),(0x6373b4,0xa9bb7bfd,"cairn_avcn"),(0xcdbc0,0xa9ba7bfd,"cairn_prctl"),(0x3dab80,0xd503233f,"cairn_stat"),(0x3def58,0xd101c3ff,"cairn_exec"),(0x3d1910,0xd10283ff,"cairn_vread"),(0x3d0aa8,0xd101c3ff,"cairn_faccess")]{assert_eq!(get32(&k,addr),original,"hook fingerprint {label}");put32(&mut k,addr,branch(addr,BASE+off(label),false));}
 k.extend_from_slice(&[0;8]);fs::write(out.join("kernel-V1.0.1.bin"),&k).unwrap();
 let mut b=fs::read(boot).unwrap();assert_eq!(&b[..8],b"ANDROID!");let version=get32(&b,40);assert!(version==3||version==4,"only GKI v3/v4");let old_size=get32(&b,8)as usize;let old_end=4096+((old_size+4095)&!4095);let new_end=4096+((k.len()+4095)&!4095);assert_eq!(old_end,new_end,"layout changed; refuse unsafe repack");assert!(b.len()>=new_end);put32(&mut b,8,k.len()as u32);b[4096..new_end].fill(0);b[4096..4096+k.len()].copy_from_slice(&k);fs::write(out.join("boot-V1.0.1.img"),&b).unwrap();
 fs::write(out.join("VERSION"),"Cairn kernel patch V1.0.1\nLinux upstream version unchanged\nAVB not re-signed\n").unwrap();
 println!("Cairn V1.0.1: payload={} bytes, kernel={}, boot={}. AVB not re-signed.",pl.len(),k.len(),b.len());
}
#[cfg(test)]mod tests{use super::*;#[test]fn branches(){assert_eq!(branch(0x100,0x104,false),0x14000001);assert_eq!(branch(0x104,0x100,true),0x97ffffff);}#[test]fn endian(){let mut b=[0;4];put32(&mut b,0,0x12345678);assert_eq!(get32(&b,0),0x12345678);}}